// Process the incoming request
const body = $input.first().json.body;
const { message, agent, expedition, chatHistory } = body;

// Ensure message exists and is a string
const safeMessage = message || '';
const safeChatHistory = chatHistory || [];

// Debug logging
console.log('N8N DEBUG - Processing request:', {
  message: safeMessage,
  chatHistoryLength: safeChatHistory.length,
  isSystemGreeting: safeMessage === '[SYSTEM_INITIAL_GREETING]'
});

// Determine what type of request this is
let requestType = 'chat';

// Only greeting if it's the special system message AND no chat history exists
if (safeMessage === "[SYSTEM_INITIAL_GREETING]" && safeChatHistory.length === 0) {
  requestType = 'greeting';
  console.log('N8N DEBUG - Routing to GREETING');
} else if (safeMessage.toLowerCase().includes('execute') || 
           safeMessage.toLowerCase().includes('start mission') ||
           safeMessage.toLowerCase().includes('begin mission') ||
           safeMessage.toLowerCase().includes('deep search')) {
  requestType = 'execute';
  console.log('N8N DEBUG - Routing to EXECUTE');
} else {
  // Default to chat for all other messages
  requestType = 'chat';
  console.log('N8N DEBUG - Routing to CHAT');
}

return {
  requestType,
  message: safeMessage,
  agent,
  expedition,
  chatHistory: safeChatHistory
};

// Generate simple greeting
const data = $input.first().json;
const { agent, expedition } = data;

const greetings = [
  `Hello! I'm ${agent.name}, ready to assist with ${expedition.name}. What would you like me to help you with?`,
  `Hi there! I'm ${agent.name}, here to help with ${expedition.name}. What specific aspects should we focus on?`,
  `Welcome! I'm ${agent.name}, assigned to ${expedition.name}. How can I assist you today?`
];

const greeting = greetings[Math.floor(Math.random() * greetings.length)];

return {
  message: greeting,
  agentReady: false,
  missionStatus: 'greeting'
};

// Deep Search Execution
const data = $input.first().json;
const { agent, expedition, message, chatHistory } = data;
const expeditionId = expedition.id || 'unknown';

// Extract search topics from conversation
function extractSearchTopics() {
  const topics = [];

  // From current message
  const words = (message || '').split(' ').filter(w => w.length > 4);
  if (words.length > 0) {
    topics.push(words.slice(0, 3).join(' '));
  }

  // From expedition name/description
  if (expedition.name) {
    topics.push(expedition.name);
  }

  // From chat history
  if (chatHistory && chatHistory.length > 0) {
    const userMessages = chatHistory.filter(m => m.role === 'user');
    userMessages.forEach(msg => {
      const msgWords = (msg.content || '').split(' ').filter(w => w.length > 5);
      if (msgWords.length > 0) {
        topics.push(msgWords.slice(0, 2).join(' '));
      }
    });
  }

  // Remove duplicates and limit
  return [...new Set(topics)].slice(0, 3);
}

const searchTopics = extractSearchTopics();

// Log mission start
try {
  await $http.request({
    method: 'POST',
    url: `${$vars.API_URL || 'http://localhost:3001'}/api/expeditions/${expeditionId}/activities`,
    headers: {
      'x-webhook-key': $vars.WEBHOOK_KEY || 'default-webhook-key',
      'Content-Type': 'application/json'
    },
    body: {
      type: 'mission_started',
      description: '🚀 DEEP SEARCH MISSION INITIATED!',
      metadata: {
        searchTopics,
        totalTopics: searchTopics.length
      }
    }
  });
} catch (error) {
  console.error('Failed to log mission start:', error);
}

// Perform searches for each topic
const searchResults = [];

for (let i = 0; i < searchTopics.length; i++) {
  const topic = searchTopics[i];

  // Log web search activity
  try {
    await $http.request({
      method: 'POST',
      url: `${$vars.API_URL || 'http://localhost:3001'}/api/expeditions/${expeditionId}/activities`,
      headers: {
        'x-webhook-key': $vars.WEBHOOK_KEY || 'default-webhook-key',
        'Content-Type': 'application/json'
      },
      body: {
        type: 'web_search',
        description: `Searching: ${topic}`,
        metadata: {
          query: topic,
          progress: Math.round(((i + 1) / searchTopics.length) * 50)
        }
      }
    });
  } catch (error) {
    console.error('Failed to log search activity:', error);
  }

  // Simulate web search results
  const results = {
    topic,
    findings: [
      {
        title: `${topic} - Market Analysis Report`,
        url: `https://research.example.com/${encodeURIComponent(topic)}`,
        snippet: `Comprehensive analysis of ${topic} with latest trends and insights.`,
        relevance: 0.9
      },
      {
        title: `Latest Developments in ${topic}`,
        url: `https://news.example.com/${encodeURIComponent(topic)}`,
        snippet: `Recent news and developments related to ${topic}.`,
        relevance: 0.8
      },
      {
        title: `${topic} Industry Overview`,
        url: `https://industry.example.com/${encodeURIComponent(topic)}`,
        snippet: `Industry overview and market dynamics for ${topic}.`,
        relevance: 0.7
      }
    ]
  };

  searchResults.push(results);

  // Log data extraction
  try {
    await $http.request({
      method: 'POST',
      url: `${$vars.API_URL || 'http://localhost:3001'}/api/expeditions/${expeditionId}/activities`,
      headers: {
        'x-webhook-key': $vars.WEBHOOK_KEY || 'default-webhook-key',
        'Content-Type': 'application/json'
      },
      body: {
        type: 'data_extraction',
        description: `Extracted ${results.findings.length} sources for ${topic}`,
        metadata: {
          topic,
          sourceCount: results.findings.length
        }
      }
    });
  } catch (error) {
    console.error('Failed to log extraction activity:', error);
  }
}

// Log analysis phase
try {
  await $http.request({
    method: 'POST',
    url: `${$vars.API_URL || 'http://localhost:3001'}/api/expeditions/${expeditionId}/activities`,
    headers: {
      'x-webhook-key': $vars.WEBHOOK_KEY || 'default-webhook-key',
      'Content-Type': 'application/json'
    },
    body: {
      type: 'analysis',
      description: 'Analyzing collected data with AI',
      metadata: {
        totalSources: searchResults.reduce((acc, r) => acc + r.findings.length, 0),
        progress: 80
      }
    }
  });
} catch (error) {
  console.error('Failed to log analysis activity:', error);
}

// Prepare comprehensive summary for OpenAI
const searchSummary = searchResults.map(r => 
  `Topic: ${r.topic}\n` +
  r.findings.map(f => `- ${f.title}: ${f.snippet}`).join('\n')
).join('\n\n');

return {
  searchResults,
  searchSummary,
  searchTopics,
  agent,
  expedition,
  expeditionId
};

// Prepare OpenAI Analysis Request
const data = $input.first().json;
const { agent, expedition, searchSummary } = data;

const systemMessage = `You are ${agent.name}, an expert in ${agent.description}. You are working on expedition: ${expedition.name}.

Based on the deep search results below, provide a comprehensive analysis and actionable insights:

${searchSummary}

Provide:
1. Key findings summary
2. Important insights and trends
3. Actionable recommendations
4. Next steps for the mission

Be thorough but concise.`;

return {
  messages: [
    {
      role: 'system',
      content: systemMessage
    },
    {
      role: 'user',
      content: 'Please analyze the search results and provide comprehensive insights for this expedition.'
    }
  ],
  model: 'gpt-4',
  temperature: 0.7,
  max_tokens: 1000,
  ...data
};

// Prepare OpenAI Chat Request
const data = $input.first().json;
const { agent, expedition, message, chatHistory } = data;

const historyText = (chatHistory || []).map(msg => `${msg.role}: ${msg.content || ''}`).join('\n');

const systemMessage = `You are ${agent.name}, an expert in ${agent.description}. You are having a conversation about expedition: ${expedition.name}.

Conversation history:
${historyText}

Respond helpfully and ask clarifying questions to better understand the mission objectives.`;

return {
  messages: [
    {
      role: 'system',
      content: systemMessage
    },
    {
      role: 'user',
      content: message || ''
    }
  ],
  model: 'gpt-4',
  temperature: 0.7,
  max_tokens: 500,
  ...data
};

// Finalize deep search mission
const analysisData = $input.first().json;
const searchData = $input.all()[0].json; // Get data from deep search node

const openaiResponse = analysisData.choices[0].message.content;
const { expeditionId, searchResults } = searchData;

// Log report generation
try {
  await $http.request({
    method: 'POST',
    url: `${$vars.API_URL || 'http://localhost:3001'}/api/expeditions/${expeditionId}/activities`,
    headers: {
      'x-webhook-key': $vars.WEBHOOK_KEY || 'default-webhook-key',
      'Content-Type': 'application/json'
    },
    body: {
      type: 'report_generation',
      description: 'Generating comprehensive mission report',
      metadata: {
        progress: 95
      }
    }
  });
} catch (error) {
  console.error('Failed to log report activity:', error);
}

// Log mission completion
try {
  await $http.request({
    method: 'POST',
    url: `${$vars.API_URL || 'http://localhost:3001'}/api/expeditions/${expeditionId}/activities`,
    headers: {
      'x-webhook-key': $vars.WEBHOOK_KEY || 'default-webhook-key',
      'Content-Type': 'application/json'
    },
    body: {
      type: 'mission_completed',
      description: '✅ Deep search mission completed successfully!',
      metadata: {
        totalSources: searchResults.reduce((acc, r) => acc + r.findings.length, 0),
        progress: 100,
        reportGenerated: true
      }
    }
  });
} catch (error) {
  console.error('Failed to log completion activity:', error);
}

return {
  message: `🚀 DEEP SEARCH COMPLETED!\n\n${openaiResponse}\n\n📊 Mission Summary:\n- Searched ${searchResults.length} topics\n- Analyzed ${searchResults.reduce((acc, r) => acc + r.findings.length, 0)} sources\n- Generated comprehensive insights\n\nCheck the activity log for detailed progress!`,
  shouldTerminateChat: true,
  agentReady: true,
  missionStatus: 'completed',
  shouldExecute: true
};

// Format OpenAI chat response
const data = $input.first().json;
const openaiResponse = data.choices[0].message.content;

return {
  message: openaiResponse,
  agentReady: false,
  missionStatus: 'planning'
};
